 lines:[["B","Huoltoyhtiö Kiinteistöhuolto, Jari puhelimessa.","Huolto, Jari.","Maintenance company, Jari speaking.","मर्मत कम्पनी, जारी बोल्दैछु।"],["A","Hei, täällä Ram Sharma. Asun osoitteessa Puistotie 5 B 12.","Moi, täällä Ram Sharma. Mä asun Puistotie viis B kakstoist.","Hi, this is Ram Sharma. I live at Puistotie 5 B 12.","नमस्ते, म राम शर्मा। म पुइस्तोतिए ५ बी १२ मा बस्छु।"],["A","Keittiön hana vuotaa. Lattialla on vettä.","Keittiön hana vuotaa. Lattialla on vettä.","The kitchen tap is leaking. There is water on the floor.","भान्साको धारा चुहिन्छ। भुइँमा पानी छ।"],["B","Sulje vesi hanan alta. Siellä on pieni venttiili.","Sulje vesi hanan alta. Siel on pieni venttiili.","Turn off the water under the tap. There is a small valve there.","धारामुनिबाट पानी बन्द गर्नुहोस्। त्यहाँ सानो भल्भ छ।"],["A","Selvä. Nyt vettä ei tule.","Okei. Nyt ei tuu vettä.","OK. Now no water is coming.","ठीक छ। अब पानी आउँदैन।"],["B","Hyvä. Tulen huomenna kello kymmenen. Oletko kotona?","Hyvä. Mä tuun huomenna kymmeneltä. Ootsä kotona?","Good. I'll come tomorrow at ten. Will you be at home?","राम्रो। म भोलि दस बजे आउँछु। तपाईं घरमा हुनुहुन्छ?"],["A","En ole. Olen luennolla. Voitko tulla iltapäivällä?","En oo. Mä oon luennolla. Voitsä tulla iltapäivällä?","No. I'm at a lecture. Can you come in the afternoon?","हुन्न। म लेक्चरमा हुन्छु। दिउँसो आउन सक्नुहुन्छ?"],["B","Kello neljä sopii. Voin myös tulla yleisavaimella.","Neljältä käy. Mä voin tulla myös yleisavaimella.","Four o'clock is fine. I can also come with the master key.","चार बजे मिल्छ। म मास्टर साँचोले पनि आउन सक्छु।"],["A","Neljä on hyvä. Kiitos!","Neljä on hyvä. Kiitti!","Four is good. Thanks!","चार बजे ठीक छ। धन्यवाद!"],["B","Ole hyvä. Kuulemiin!","Ole hyvä. Kuulemiin!","You're welcome. Goodbye!","केही छैन। नमस्कार!"]],
 key:[["… vuotaa.","… is leaking.","… चुहिन्छ।"],["… ei toimi.","… doesn't work.","… चल्दैन।"],["Asun osoitteessa …","I live at (address) …","म … ठेगानामा बस्छु।"],["Sulje vesi.","Turn off the water.","पानी बन्द गर।"],["Voitko tulla …?","Can you come …?","… आउन सक्नुहुन्छ?"],["Kuulemiin!","Goodbye! (on the phone)","नमस्कार! (फोनमा)"]],
 grammar:["Location: keittiössä, lattialla, hanan alla","Imperative: Sulje vesi!","Questions: Oletko kotona? Voitko tulla?"],
 q:[["mc","Mikä vuotaa?","What is leaking?",["suihku","keittiön hana","patteri"],1],["mc","Mitä Ram tekee ensin?","What does Ram do first?",["soittaa naapurille","sulkee veden","menee luennolle"],1],["mc","Milloin huoltomies tulee?","When does the caretaker come?",["kello 10","kello 16","illalla"],1],["tf","Ram on kotona kello kymmenen.","Ram is at home at ten.",false]],
